from math import comb
from fractions import Fraction as F
from itertools import product,combinations
import sympy as S
from .authoring import maker,finish
from .common import section
q=maker('combinatorial-identities',['double counting','coefficient models','cancellation involutions'])
x=S.Symbol('x')
p=[
q(1,r'Find $\sum_{k=0}^{8}\binom8k^2$.',12870,[(256,'Sum one binomial row instead of its squared entries.'),(65536,'Square the sum of the row.'),(6435,'Count only half of the size-eight subsets.'),(4900,'Keep only the middle summand.')],[r'Choose eight objects from two disjoint groups of eight.',r'If k come from the first group, the number is C(8,k)C(8,8-k)=C(8,k)².',r'Summing over k counts all C(16,8)=12870 choices.'],['Interpret the product as independent choices from two groups.','Use binomial symmetry to make the selected totals constant.'],'Recognize a binomial sum as a partition of one counting problem.',lambda:S.expand((1+x)**16).coeff(x,8),'Independent polynomial coefficient.',2),
q(2,r'Find $\sum_{k=0}^{10}k\binom{10}k$.',5120,[(1024,'Count subsets without their marked element.'),(10240,'Allow the marked element to be absent.'),(2560,'Identify complementary subsets despite the marked element.'),(2520,'Keep only the central subset size.')],[r'Count pairs consisting of a subset and one marked element inside it.',r'Choose the marked element in ten ways. Each of the other nine elements may be included or excluded independently.',r'The count is 10·2^9=5120.'],['The multiplier k can represent a marked member of a k-element set.','Choose that marked member before choosing the rest.'],'Reverse the order of choosing a subset and its marked member.',lambda:sum(mask.bit_count() for mask in range(1<<10)),'Independent enumeration of all subset sizes.',2),
q(3,r'Find $\sum_{k=0}^{8}k(k-1)\binom8k$.',3584,[(1792,'Treat the two marked elements as an unordered pair.'),(16384,'Allow either marked element to be absent.'),(2048,'Mark only one element.'),(4096,'Allow the two marked elements to coincide.')],[r'The multiplier counts ordered pairs of distinct marked elements in the subset.',r'Choose them in 8·7 ways, then freely include or exclude the remaining six elements.',r'The result is 8·7·2^6=3584.'],['Interpret k(k-1) as an ordered choice of two distinct members.','After marking them, only six inclusion decisions remain.'],'Use ordered marking to evaluate a weighted binomial sum.',lambda:sum(mask.bit_count()*(mask.bit_count()-1) for mask in range(1<<8)),'Independent subset enumeration.'),
q(4,r'What is the coefficient of $x^6$ in $(1+x)^8(1+x)^5$?',1716,[(56,'Use only the first factor’s coefficient.'),(1287,'Select five rather than six of the thirteen factors.'),(3003,'Use the central coefficient of fourteen factors.'),(13,'Count the factors rather than choices of six of them.')],[r'The product has thirteen factors of (1+x), so it equals (1+x)^13.',r'A term x^6 arises by selecting x from exactly six factors.',r'The coefficient is C(13,6)=1716.'],['Combine the equal bases before expanding.','Interpret the coefficient as a choice of factors contributing x.'],'Simplify a coefficient model before calculation.',lambda:S.expand((1+x)**8*(1+x)**5).coeff(x,6),'Direct exact polynomial multiplication.',2),
q(5,r'Find $\sum_{k=0}^{6}(-1)^k k^2\binom6k$.',0,[(672,'Ignore the alternating signs.'),(192,'Count only the single-mark portion without signs.'),(64,'Remove the weight but ignore signs.'),(36,'Keep only the last term.')],[r'Split k² into k(k-1)+k, corresponding to two distinct ordered marks or one mark.',r'For fixed marks, at least one of the other elements is free. Toggle the least unmarked element: this preserves the marks but reverses subset parity.',r'Terms cancel in pairs in both weighted sums, giving zero. The toggle is its own inverse and has no fixed point.'],['Replace k² by a sum of two combinatorial marking counts.','Pair positive and negative contributions by toggling an unmarked element.'],'Prove alternating cancellation with a sign-reversing involution.',lambda:sum((-1)**k*k*k*comb(6,k) for k in range(7)),'Independent exact summation.'),
q(6,r'Find $\binom33+\binom43+\cdots+\binom93$.',210,[(120,'Stop the containing set one element early.'),(84,'Keep only the last summand.'),(252,'Use the wrong lower index after summation.'),(165,'Shift the upper endpoint incorrectly.')],[r'Count four-element subsets of {1,...,10} by their largest member j.',r'For j=4 through 10, the other three members have C(j-1,3) choices.',r'The sum is therefore C(10,4)=210.'],['Classify subsets by their largest element.','The largest element is fixed; choose the others below it.'],'Derive the hockey-stick identity through a largest-element partition.',lambda:len(list(combinations(range(10),4))),'Independent direct combination count.',2),
q(7,r'How many ordered pairs of subsets (A,B) of a five-element set satisfy A⊆B?',243,[(1024,'Choose A and B independently without containment.'),(32,'Choose only B.'),(64,'Allow only two joint membership states.'),(120,'Treat subset choices as permutations.')],[r'Each element is either in neither set, in B only, or in both.',r'These three states are independent across five distinct elements.',r'The count is 3^5=243. This also proves $\sum_k\binom5k2^k=3^5$ by choosing B first.'],['List the allowed joint membership states of one element.','Containment forbids the state in A but not in B.'],'Replace nested subset choices by independent local states.',lambda:sum(a&~b==0 for a in range(32) for b in range(32)),'Independent bitmask containment enumeration.'),
q(8,r'How many ordered pairs of nonempty disjoint subsets (A,B) of a six-element set are there?',602,[(729,'Allow either subset to be empty.'),(601,'Subtract the doubly counted empty-empty pair twice.'),(665,'Exclude only one empty subset.'),(301,'Identify the ordered pair with its reversal.')],[r'Without the nonempty conditions, each element has three states: A, B, or neither, giving 3^6.',r'If A is empty there are 2^6 possibilities; the same holds for B. Their intersection is the single empty-empty pair.',r'The count is 3^6-2·2^6+1=602.'],['Use three local membership states for disjointness.','Then remove emptiness with inclusion–exclusion.'],'Combine a local-state encoding with global nonempty constraints.',lambda:sum(a and b and not(a&b) for a in range(64) for b in range(64)),'Independent disjoint bitmask enumeration.'),
q(9,r'Find $\sum_{k=0}^{8}\frac{\binom8k}{k+1}$.',F(511,9),[(F(512,9),'Include the missing zero-index term of the next row.'),(256,'Ignore the denominator.'),(F(255,9),'Use the wrong binomial-row total.'),(511,'Omit the common factor one ninth.')],[r'The factorial definition gives C(8,k)/(k+1)=C(9,k+1)/9.',r'The new lower index runs from one through nine, so the sum is one ninth of the ninth row with its first entry omitted.',r'The result is (2^9-1)/9=511/9.'],['Absorb k+1 into a factorial denominator.','Track the shifted summation endpoints.'],'Shift a binomial coefficient while preserving boundary terms.',lambda:sum(F(comb(8,k),k+1) for k in range(9)),'Independent exact rational summation.'),
q(10,r'What is the constant term in $(x^2+x^{-1})^9$?',84,[(126,'Choose four factors without solving the exponent equation.'),(36,'Choose two factors.'),(1,'Assume a constant comes only from constant factors.'),(0,'Assume positive and negative exponents cannot cancel.')],[r'Choose x² from k factors and x^-1 from the remaining 9-k factors.',r'The exponent is 2k-(9-k)=3k-9, which vanishes at k=3.',r'There are C(9,3)=84 such choices.'],['Track the total exponent from both kinds of factor choices.','Set that exponent equal to zero before counting.'],'Turn a constant-term condition into an integer exponent equation.',lambda:S.expand((x*x+1/x)**9).coeff(x,0),'Direct Laurent-polynomial expansion.'),
q(11,r'Find the coefficient of $x^5$ in $(1+x+x^2)^5$.',51,[(126,'Allow exponents larger than two from each factor.'),(75,'Count the excluded exponent assignments.'),(50,'Miss the all-ones exponent assignment.'),(243,'Count every term regardless of its exponent.')],[r'The coefficient counts five coordinates from {0,1,2} summing to five.',r'Without caps there are C(9,4)=126. A specified coordinate at least three leaves C(6,4)=15; two violations are impossible.',r'Thus the coefficient is 126-5·15=51.'],['Interpret each factor as one bounded exponent choice.','Use a bounded composition count for the target exponent.'],'Connect polynomial coefficients with constrained compositions.',lambda:S.expand((1+x+x*x)**5).coeff(x,5),'Independent polynomial multiplication.'),
q(12,r'How many paths from (0,0) to (4,4), using unit east and north steps, never have y>x?',14,[(70,'Ignore the boundary restriction.'),(35,'Assume exactly half the paths stay below the diagonal.'),(56,'Count the forbidden paths.'),(20,'Use a smaller unrestricted path count.')],[r'There are C(8,4)=70 paths in all.',r'Reflect the prefix through the first step reaching y=x+1. This bijects forbidden paths with paths having five east and three north steps, counted by C(8,3)=56.',r'The valid count is 70-56=14. Reflection must stop at the first crossing to make the map reversible.'],['Count paths that cross the diagonal and identify their first crossing.','Reflect only the prefix up to that crossing.'],'Use a reversible reflection map for a path boundary.',lambda:sum(all(sum(t[:j])<=j-sum(t[:j]) for j in range(9)) for t in product([0,1],repeat=8) if sum(t)==4),'Independent enumeration of all balanced step strings.'),
q(13,r'How many subsets of a nine-element set have odd size at least three?',247,[(256,'Include the one-element subsets.'),(255,'Remove only the empty set, which is even.'),(502,'Start with all subsets and subtract the wrong sizes.'),(126,'Count only the largest central odd size.')],[r'Toggling a fixed element pairs every even-sized subset with an odd-sized subset.',r'Exactly half of the 2^9 subsets have odd size, so there are 256.',r'Exclude the nine singleton subsets to obtain 247.'],['Pair even and odd subsets using one fixed element.','Remove only the odd sizes disallowed by the lower bound.'],'Combine a parity involution with an endpoint exclusion.',lambda:sum(mask.bit_count()%2==1 and mask.bit_count()>=3 for mask in range(512)),'Independent subset enumeration.',2),
q(14,r'For an integer n≥3, $\binom n3=4\binom n2$. Find n.',14,[(12,'Forget the subtract-two in the coefficient ratio.'),(6,'Cancel the wrong factorial factors.'),(15,'Shift the index one step too far.'),(8,'Replace the coefficient ratio by n/2.')],[r'Both coefficients are positive, so divide by C(n,2).',r'The ratio simplifies to (n-2)/3=4.',r'Thus n=14; C(14,3)=364 and 4C(14,2)=364 verify it.'],['Cancel the shared factorial factors before expanding numbers.','The ratio of adjacent binomial coefficients is simple.'],'Use factorial cancellation with a nonzero denominator.',lambda:next(n for n in range(3,100) if comb(n,3)==4*comb(n,2)),level=2)]
e=[
q(101,r'From eight people, a five-person committee and one chair on that committee are chosen. How many outcomes are possible?',280,[(56,'Choose the committee but not the chair.'),(448,'Allow the chair to be outside the committee.'),(168,'Choose the wrong number of remaining members.'),(560,'Give the chair an extra binary label.')],[r'Choosing the committee first gives C(8,5) choices, followed by five chair choices.',r'Choosing the chair first gives eight choices, followed by C(7,4) choices of other committee members.',r'Both procedures count the same objects exactly once, so the common value is 5·56=8·35=280.',r'The equality is more useful than the numerical answer: it derives kC(n,k)=nC(n-1,k-1), which evaluates weighted sums after the choice order is reversed.'],['The chair must belong to the selected committee.','Count in both possible orders.'],'Derive a marked-element identity by double counting.',lambda:sum(len(c) for c in combinations(range(8),5)),'Independent enumeration of committee-chair outcomes.',2),
q(102,r'Six objects are chosen from two disjoint groups of five and seven. Evaluate $\sum_k\binom5k\binom7{6-k}$, where impossible choices contribute zero.',924,[(462,'Use a containing set of eleven rather than twelve.'),(252,'Assume only the first group matters.'),(210,'Count just one split between the groups.'),(1848,'Count the two group labels as interchangeable orders.')],[r'The summand counts selections with exactly k objects from the first group and 6-k from the second.',r'These cases partition all six-object selections from the twelve-object union.',r'Therefore the sum is C(12,6)=924.',r'Including impossible k values as zero makes the notation concise, but does not create new cases. The proof depends on disjoint groups and a fixed total selected size.'],['Interpret each factor as a choice from one group.','Every six-element selection has a unique value of k.'],'Prove Vandermonde’s identity as an exhaustive partition.',lambda:comb(12,6),'Independent unrestricted six-object combination count.',2)]
finish('combinatorial-identities','Double counting, coefficients & cancellation','Counting','constrained-counting recurrence polynomial-structure',6,'91–104',
 [r'A combinatorial identity is often one set of objects described in two different ways. Instead of manipulating a long sum immediately, ask what the summand counts, what the index records, and whether the cases partition a simpler whole.',r'This study develops three representations: marked subsets for weighted sums, local choices for polynomial coefficients, and reversible pairings for cancellations. Each representation turns an algebraic expression into a structure that can be checked.'],
 [section('Change the order of counting',r'A factor k multiplying C(n,k) can mark one member of a selected subset. Choose the subset first and then its mark, or choose the mark first and freely choose other members. A factor k(k-1) marks an ordered pair of distinct members. The distinction between ordered and unordered marks explains a possible factor of two.',r'Vandermonde’s identity partitions fixed-size selections from two disjoint groups according to how many came from the first group. Binomial symmetry can make an expression such as C(n,k)² fit this pattern. State the containing set and the total selected size before replacing a sum by a single coefficient.',r'The hockey-stick identity partitions subsets by their largest member. The endpoint shift comes from fixing that largest member and choosing all remaining members below it. This interpretation prevents a memorized identity from acquiring an incorrect upper index.'),
 section('Coefficients encode local choices',r'In a product of polynomials, choose one term from each factor. The exponents add, and the product of coefficients counts the ways to make that choice. A target coefficient therefore imposes a sum constraint on local exponent choices.',r'A constant term in a Laurent polynomial is not necessarily absent just because no factor contains a constant. Positive and negative exponents can cancel. Write the total exponent in terms of the number of each type of choice, solve the integer equation, and then count the choices satisfying it.',r'For factors 1+x+x², each local exponent is bounded. The coefficient of a target power is a bounded composition count, so stars and bars alone overcounts. Inclusion–exclusion removes assignments that choose a forbidden exponent, and direct polynomial multiplication gives a useful independent check.'),
 section('Use reversible cancellation and reflection',r'Toggling one fixed element pairs even-sized and odd-sized subsets. The toggle is its own inverse and has no fixed points, so the two classes have equal size. With marked elements, toggle an unmarked element to preserve the marks while changing the sign in an alternating sum.',r'A reflection map can similarly count paths forbidden by a diagonal boundary. Locate the first crossing, reflect only the prefix up to that crossing, and describe how to reverse the map. Reflecting an arbitrary prefix would not establish a bijection.',r'When a denominator such as k+1 appears in a binomial sum, factorial cancellation may shift the coefficient into the next row. Track both the scale factor and the new endpoints. A missing row endpoint often contributes the small correction that distinguishes the exact finite answer from a tempting nearby value.')],
 ['Interpret weighted binomial sums through marked objects.','Model coefficients as bounded exponent choices.','Prove cancellation and boundary-path counts with reversible maps.'],
 [r'Count committee-chair pairs in both orders to derive kC(n,k)=nC(n-1,k-1).',r'Partition a selection from two groups by its first-group size to derive Vandermonde.',r'Toggle a fixed unmarked element to pair opposite signs without changing the counted structure.'],
 'A suggestive algebraic match is not yet a counting proof. Specify the objects, the cases, and the inverse map so that no object is lost or counted twice.',e,p,
 dict(prompt=r'Explain why $\sum_{k=0}^{7}k\binom7k=448$ without adding the eight summands.',answer=r'Choose a marked member first: $7\cdot2^6=448$.',steps=[r'The summand counts a k-element subset with one distinguished member.',r'There are seven choices for that member and independent inclusion choices for the other six.']),
 ['marked-element double counting','Vandermonde partitions','coefficient encodings','reflection and involution'],
 [(r'k\binom nk=n\binom{n-1}{k-1}','Marked-element identity','reversing the order of selecting a subset and one member of it','$1\\le k\\le n$; the marked element belongs to the subset.'),(r'\sum_k\binom ak\binom b{r-k}=\binom{a+b}r','Vandermonde identity','combining fixed-size selections from two disjoint groups','a,b are nonnegative integers; impossible binomial choices count as zero.'),(r'\sum_{k=r}^{n}\binom kr=\binom{n+1}{r+1}','Hockey-stick identity','summing binomial choices partitioned by their largest selected element','$n\\ge r\\ge0$; preserve the one-step shift in both indices.'),(r'C_n=\binom{2n}n-\binom{2n}{n-1}','Diagonal-path reflection count','counting balanced lattice paths that never cross above the diagonal','Paths use n east and n north steps from the origin; the boundary itself is allowed.')], 'combinations')
